interface RecordingState {
  isRecording: boolean;
  mode: RecordingMode | null;
  duration: number;
  outputFiles: { screen?: string; webcam?: string };
  startRecording: (mode: RecordingMode) => Promise<void>;
  stopRecording: () => Promise<void>;
  updateDuration: (duration: number) => void;
}
